import { Box, CircularProgress } from "@mui/material";
import React, { useState, useEffect } from "react";
import { Navigate } from "react-router-dom";

/**
 * routerでページ遷移をする際に判定をして、trueの時はredirectComponentに、falseの時は別のページへアクセスします。
 * @param {Function} judgElement - 非同期関数で、判定を行う。
 * @param {React.ComponentType} RedirectComponent - 判定がtrueの時に表示するコンポーネント。
 * @param {string} redirectPath - 判定がfalseの時にリダイレクトするパス。
 * @returns {JSX.Element} - 判定に基づいて適切なコンポーネントを返します。
 */
export default function RouteCheck({ judgElement, RedirectComponent, redirectPath }) {
    const [isLoading, setIsLoading] = useState(true);
    const [isResult, setResult] = useState(false);

    useEffect(() => {
        async function fetchData() {
            const result = await judgElement();
            setResult(result);
            setIsLoading(false);
        }

        fetchData();
    }, [judgElement]);

    if (isLoading) {
        return (
            <Box
                justifyContent="center"
                alignItems="center"
                height="100vh"
                width="100%"
            >
                <CircularProgress color="black" />
            </Box>
        )
    }

    return isResult ? <RedirectComponent /> : <Navigate to={redirectPath} />;
}
